import fs from "node:fs";
import path from "node:path";
import yaml from "js-yaml";
import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

/**
 * The notebook holds living articles — pieces that get revised rather than
 * dated. One category per project under ~/code/open-concept-lab/ai/.
 *
 * Written by hand rather than autogenerated. Autogeneration derives the tree
 * from the files, and the files do not know that a project with one page and a
 * project with three are the same kind of thing: one would render as a bare
 * directory name, the other as a tree. Here every project reads the same at the
 * row — a name, the stage it is at, and a few words saying what it is.
 *
 * What differs is only whether the row opens. A project whose overview is all
 * there is does not open; a project with further pages does, and they sit under
 * it. That is not a second shape, it is the absence of a lie: an earlier version
 * gave every project a child called "Overview", which is not the name of a page
 * but the name of a position, printed five times down a rail eleven rows long.
 * The overview is now what the project's own name links to.
 *
 * The stage comes from data/projects.yml, so it is set in one place and the
 * home page and the sidebar cannot disagree.
 */

type ProjectRow = { name: string; tone?: string };

const projects = (
  yaml.load(
    fs.readFileSync(path.join(__dirname, "data/projects.yml"), "utf8"),
  ) as { projects: ProjectRow[] }
).projects;

const toneOf = (name: string): string =>
  projects.find((p) => p.name === name)?.tone ?? "draft";

const project = (
  id: string,
  blurb: string,
  items: { label: string; doc: string }[],
) => {
  const customProps = { blurb, status: toneOf(id) };

  // Nothing beyond the overview: one row, and it goes straight there.
  if (items.length === 0) {
    return { type: "doc" as const, id: `${id}/index`, label: id, customProps };
  }

  return {
    type: "category" as const,
    label: id,
    collapsed: false,
    customProps,
    // The label itself is the overview, so no child has to stand in for it.
    link: { type: "doc" as const, id: `${id}/index` },
    items: items.map((i) => ({
      type: "doc" as const,
      id: `${id}/${i.doc}`,
      label: i.label,
    })),
  };
};

const sidebars: SidebarsConfig = {
  notebookSidebar: [
    { type: "doc", id: "index", label: "Notebook" },
    // Not a project, so it does not sit among them. Above the projects rather
    // than below, because it is the context they sit in: what the field asked
    // for this year, then what was done about it, then how the pages are
    // written. Two flat rows bracketing the project tree read as a dumping
    // ground; one at each end reads as a frame.
    { type: "doc", id: "mech-interp-2026", label: "The field in 2026" },
    project("edit-slice", "what edits disturb", [
      { label: "Paper", doc: "review" },
      { label: "Evidence", doc: "ledger" },
    ]),
    project("edit-reach", "predicting reach", [
      { label: "Paper", doc: "paper" },
    ]),
    project("rome-neighbors", "geometry", []),
    project("claim-graph", "claims as nodes", []),
    project("opz", "deployment labs", []),
    { type: "doc", id: "writing-here", label: "Writing here" },
  ],
};

export default sidebars;
